def parse_duration(text: str) -> int:
    """Convert a duration in "H:M" format into total minutes.

    Raises ValueError if the text is malformed, hours are negative or
    minutes are outside the range 0-59.
    """
    parts = text.split(":")
    if len(parts) != 2:
        raise ValueError(f"Invalid duration {text!r}: expected format 'H:M'")
    try:
        hours = int(parts[0])
        minutes = int(parts[1])
    except ValueError as exc:
        raise ValueError(f"Invalid duration {text!r}: hours and minutes must be integers") from exc
    if hours < 0 or not 0 <= minutes < 60:
        raise ValueError(f"Invalid duration {text!r}: hours must be >= 0 and minutes between 0 and 59")
    return hours * 60 + minutes

